module counter_mux_module (
  input clk,
  input reset,
  output reg [1:0] out
);

reg [2:0] count;

always @(posedge clk) begin
  if (reset) begin
    count <= 0;
  end else begin
    if (count == 6) begin
      count <= 0;
    end else begin
      count <= count + 1;
    end
  end
end

always @* begin
  case (count)
    0: out = 2'b00;
    1: out = 2'b01;
    2, 3: out = 2'b10;
    4, 5, 6: out = 2'b11;
  endcase
end

endmodule
