    wire [4:0] temp_carry;

    // Full adder for the least significant bit
    full_adder FA0(
        .a(A[0]),
        .b(B[0]),
        .c(Cin),
        .sum(temp_sum[0]),
        .carry(temp_carry[0])
    );

    // Full adder for the second least significant bit
    full_adder FA1(
        .a(A[1]),
        .b(B[1]),
        .c(temp_carry[0]),
        .sum(temp_sum[1]),
        .carry(temp_carry[1])
    );

    // Full adder for the third least significant bit
    full_adder FA2(
        .a(A[2]),
        .b(B[2]),
        .c(temp_carry[1]),
        .sum(temp_sum[2]),
        .carry(temp_carry[2])
    );

    // Full adder for the most significant bit
    full_adder FA3(
        .a(A[3]),
        .b(B[3]),
        .c(temp_carry[2]),
        .sum(temp_sum[3]),
