module up_down_counter (
    input clk, reset, LD, UD,
    input [3:0] LOAD_IN,
    output reg [6:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 7'b0;
    end else begin
        if (LD) begin
            Q <= LOAD_IN;
        end else if (UD) begin
            Q <= Q + 1;
        end else begin
            Q <= Q - 1;
        end
    end
end

endmodule

module shift_register (
    input clk,
    input load,
    input serial_in,
    output reg [2:0] out
);

always @(posedge clk) begin
    if (load) begin
        out <= 3'b0;
    end else begin
        out <= {out[1:0], serial_in};
    end
end

endmodule

