  wire data_in;
  wire irq;
  reg irq_mask;
  wire read_mux_out;
  reg [31:0] readdata;
  assign clk_en = 1;

  // s1, which is an e_avalon_slave
  assign read_mux_out = ({1 {(address == 0)}} & data_in) |
                        ({1 {(address == 2)}} & irq_mask);

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
