module signed_mag_comp (
    input signed [3:0] A,
    input signed [3:0] B,
    output eq,
    output gt,
    output lt,
    output [3:0] abs_A,
    output [3:0] abs_B
);

    assign eq = (A == B);
    assign gt = (A > B);
    assign lt = (A < B);
