	input clk,
	input Tx_start,
	input [23:0] dbuffer,
	output Tx,
	output Tx_busy
);

wire bittick;

wire[7:0] Tx_data = dbuffer[7:0];

RS232Baud baud(
	.clk(clk),
	.enable(Tx_busy),
	.tick(bittick)
);

reg[3:0] Tx_state = 0;
wire Tx_ready = (Tx_state==0);
assign Tx_busy = ~Tx_ready;

